      for (let u = 0; u < n; u++) {
        if (state[u]) continue;
        if (!ok(u)) { snap("完成", "找到了环，环上的课永远上不完，返回 <b>false</b>。", view(-1), { at: "done", kind: "warn", ans: false }); return; }
